//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT95030.gfm';
// 전역 변수 선언
scwin.stFocusGrid = false;

/*---------------------------------------------------------------------------------------------------------*/
scwin.js_com_Isurcd; //발행사코드
scwin.js_com_Isurnm; //발행사명
scwin.js_com_market = $c.frame.path("/top").ps_market; //운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market !== "1" && scwin.js_com_market !== "2") scwin.js_com_market = "";
//if (typeof(js_com_market)=="undefined") {js_com_market = ""; }else{ js_com_market = js_market; }

scwin.js_com_left;
scwin.js_com_top;

//----W-Craft WebSquare 변환 확인: Focus----//

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.txb_isur_cd_onblur = function() {

    //----W-Craft WebSquare 변환 확인: Focus----//
    if (scwin.stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.value === "") {
        txb_com_abbrv.setValue("");
    }
};

scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "";
};

scwin.txb_isur_cd_onkeyup = function(e) {
    if (e.keyCode === 40) {
        //아래화살표눌렀을때 그리드로 포커스

        //----W-Craft WebSquare 변환 확인: Focus----//
        Grd_com_isur.Focus();
    } else {
        if (e.keyCode === 13) {
            $c.cm.fn_com_Confirm_set();
        } else {
            $c.cm.fn_com_isur_nm(e.keyCode);
        }
    }
};

scwin.btn_Search_onclick = function(e) {
    scwin.listSync();
};

scwin.img_com_srch_onclick = function(e) {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};

scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === 13) {
        $c.cm.fn_com_Confirm_set();
    }
};

scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnSetFocus = function() {

    //----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = true;
};

//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnKillFocus = function() {

    //----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

scwin.dts_BaseInfo_OnLoadCompleted = function(e) {
    //CloseWin(rowcount, grid_BaseInfo);  

};

scwin.grid_BaseInfo_OnDblClick = function(row, colid) {
    if (colid === "ACPT_NO") {
        let gAcptNo = dts_BaseInfo.getCellData(row, "ACPT_NO");
        scwin.kindViewer(gAcptNo);
    }
};

scwin.grd_FisInfo_OnDblClick = function(row, colid) {
    if (row === 1) {
        if (colid === "INDVDL_VAL1") {
            let gAcptNo = dts_FisInfo.getCellData(row, "INDVDL_VAL1");
            scwin.kindViewer(gAcptNo);
        } else if (colid === "CONSFS_VAL1") {
            let gAcptNo = dts_FisInfo.getCellData(row, "CONSFS_VAL1");
            scwin.kindViewer(gAcptNo);
        }
    }
};

scwin.grd_subcom_OnDblClick = function(row, colid) {
    if (colid === "ACPT_NO") {
        let gAcptNo = dts_SubCom.getCellData(row, "ACPT_NO");
        scwin.kindViewer(gAcptNo);
    }
};

scwin.grd_subscom_OnDblClick = function(row, colid) {
    if (colid === "ACPT_NO") {
        let gAcptNo = dts_SubSCom.getCellData(row, "ACPT_NO");
        scwin.kindViewer(gAcptNo);
    }
};

scwin.grd_OthCorpCotrb_OnDblClick = function(row, colid) {
    if (colid === "ACPT_NO") {
        let gAcptNo = dts_OthCorpCotrb.getCellData(row, "ACPT_NO");
        scwin.kindViewer(gAcptNo);
    }
};

scwin.dts_BaseInfo_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_BaseInfo);
};

scwin.dts_FisInfo_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_FisInfo);
};

scwin.dts_SubCom_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_SubCom);
};

scwin.dts_SubSCom_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_SubSCom);
};

scwin.dts_SubCom_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_SubCom);
};

scwin.dts_OthCorpCotrb_OnLoadError = function(e) {
    $c.win.alert + $c.data.getMessage(dts_OthCorpCotrb);
};

// 일반 함수
scwin.listSync = function() {
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_BaseInfo",
        action : "/kclic.do",
        ref : "",
        target : "dts_BaseInfo=body.content",
        submitDoneHandler : scwin.dts_BaseInfo_OnLoadCompleted,
        submitErrorHandler : scwin.dts_BaseInfo_OnLoadError,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_FisInfo",
        action : "/kclic.do",
        ref : "",
        target : "dts_FisInfo=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitErrorHandler : scwin.dts_FisInfo_OnLoadError,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions3 = {
        id : "sbm_dts_SubCom",
        action : "/kclic.do",
        ref : "",
        target : "dts_SubCom=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitErrorHandler : scwin.dts_SubCom_OnLoadError,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);


    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions4 = {
        id : "sbm_dts_SubSCom",
        action : "/kclic.do",
        ref : "",
        target : "dts_SubSCom=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitErrorHandler : scwin.dts_SubSCom_OnLoadError,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions4);


    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions5 = {
        id : "sbm_dts_OthCorpCotrb",
        action : "/kclic.do",
        ref : "",
        target : "dts_OthCorpCotrb=body.content",
        // TODO Stage2: 원본 submission에 submitdone 없음
        submitErrorHandler : scwin.dts_OthCorpCotrb_OnLoadError,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions5);



    //ShowWin(grid_BaseInfo);

};

scwin.kindViewer = function(acptNo) {
    if (acptNo !== '') {
        let dstUrl;
        dstUrl = in_kind_url;
        const wUrl = dstUrl + "/common/disclsviewer.do?method=searchInitInfo&acptno=" + acptNo;

        //----W-Craft WebSquare 변환 확인: open----//
        window.open(wUrl, acptNo, "top=100, left=100, width=1024, height=768, scrollbars=yes, toolbar=no, resizable=yes");
    }
};

scwin.isurSearch_Rtn = function(pJongCode, pJongNm) {
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);
};

scwin.comIsur = function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    $c.cm.fn_com_grid_pos(grdObj, grdObj2);
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_com_isur_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    $c.cm.fn_com_isur_sync();
};

scwin.comConfirmSet = function() {

    //----W-Craft WebSquare 변환 확인: Focus----//
    const pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "ISUR_CD");

    //----W-Craft WebSquare 변환 확인: Focus----//
    const pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "COM_ABBRV");
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);

    //----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

scwin.comIsurSync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/isurcd.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_com_isur_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.IsurcdSearch = async function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; //발행사코드
    scwin.js_com_Isurnm = grdObj2; //발행사명
    $c.cm.IsurTagetPos(grdObj, grdObj2, 'E');

    //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    const options = {
        id: "ULDCOM00007",
        title: "발행회사검색창",
        type: "pageFramePopup",
        width: "295px",
        height: "400px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/common/ULDCOM00007.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};

scwin.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    let cL = 7;
    let cT = 53;
    if (Tg === "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = scwin.js_com_left.substring(0, scwin.js_com_left.length - 2);
    scwin.js_com_left = eval(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = scwin.js_com_top.substring(0, scwin.js_com_top.length - 2);
    scwin.js_com_top = eval(scwin.js_com_top) + cT;
};

scwin.comGridPos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; //발행사코드
    scwin.js_com_Isurnm = grdObj2; //발행사명
    $c.cm.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;
};

scwin.comIsurNm = function(keyCode) {
    let cnt = 0;
    const len = scwin.js_com_Isurcd.getValue().length;
    const txtVal = scwin.js_com_Isurcd.getValue().toUpperCase();
    let foColum = 1;
    if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum === 1) {
        MxDataSet_com_isur.sort("+COM_ABBRV", 0);
        MxDataSet_com_isur.sort('', 0);
        for (i = 1; i <= MxDataSet_com_isur.getRowCount(); i++) {
            let name = MxDataSet_com_isur.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.sort("+ISUR_CD", 0);
        MxDataSet_com_isur.sort('', 0);
        for (i = 1; i <= MxDataSet_com_isur.getRowCount(); i++) {
            let name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }

    //----W-Craft WebSquare 변환 확인: Focus----//
    MxDataSet_com_isur.setFocusedCell(cnt + 11, 0);

    //----W-Craft WebSquare 변환 확인: Focus----//
    MxDataSet_com_isur.setFocusedCell(cnt, 0);
};

scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_1);
    MxTab_1.ActiveIndex = 1;
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
